package com.autojobapply.application;
import com.autojobapply.config.Config; import com.autojobapply.model.*; import com.autojobapply.tracking.ApplicationTracker;
/** Guard rail: public job feeds do not authorize form submission. An employer-authorized API adapter is required. */
public final class SubmissionService { private final Config config;private final ApplicantProfile profile;private final ApplicationTracker tracker;public SubmissionService(Config c,ApplicantProfile p,ApplicationTracker t){config=c;profile=p;tracker=t;}
 public ApplicationStatus process(ScoredJob job){String reason;if(!config.autoSubmit()){reason="Automatic submission disabled by configuration"; tracker.record(job,ApplicationStatus.BLOCKED,reason);return ApplicationStatus.BLOCKED;}if(profile.get("email").isBlank()||profile.get("legal.name").isBlank()){reason="Verified legal name or email is unavailable";tracker.record(job,ApplicationStatus.BLOCKED,reason);return ApplicationStatus.BLOCKED;}ApplicationStatus result=new GreenhouseApplicationAdapter().apply(job,profile,config.resumePath(),config.authorizedSubmission());reason=result==ApplicationStatus.SUBMITTED?"Employer confirmation detected":result==ApplicationStatus.APPLYING?"Greenhouse form filled; final submission disabled":result.name();tracker.record(job,result,reason);return result;}}
